 if(action==='fit_bionics'&&!other.some(x=>gtPcLasting(x).length))return 'No Lasting Injuries';
 if(action==='visit_chop_shop'&&!gtPcDamages(f).length)return 'No Lasting Damage';
 if(action==='suit_evolution'&&Number(f.killCount??f.kill_count??f.kills??0)<4)return 'Needs 4 kills';
