 if(!gtPcEligible(g,f).some(x=>x.id===row.action))issues.push(`${gtPcName(f)} cannot perform this action.`);
 const reason=gtPcReason(g,f,row.action);if(reason)issues.push(reason);
 if(['medical_escort','fit_bionics'].includes(row.action)){
  if(!target)ready=false;
  else if(target.id===f.id||!gtPcLive(target))issues.push('Choose another living fighter to take to the Doc.');
  else {if(rows.has(target.id))issues.push(`${gtPcName(target)} has an action of their own.`);if([...rows].some(([fid,r])=>fid!==f.id&&r.targetFighterId===target.id))issues.push(`${gtPcName(target)} is already being taken to the Doc.`);if(row.action==='medical_escort'&&!gtPcCritical(target).length)issues.push(`${gtPcName(target)} has no Critical Injury to treat.`);if(row.action==='fit_bionics'){let valid=new Set(gtPcLasting(target).map(x=>x.id));if(!row.injuryIds?.length)ready=false;else if(!row.injuryIds.every(x=>valid.has(x)))issues.push(`Choose Lasting Injuries that ${gtPcName(target)} has.`);}}
 }
 if(row.action==='develop_tactics'){if(!row.tacticsCard)ready=false;else if([...rows].some(([fid,r])=>fid!==f.id&&r.tacticsCard?.id===row.tacticsCard.id))issues.push(`${row.tacticsCard.name} is already being developed.`);}
 if(row.action==='visit_chop_shop'){let valid=new Set(gtPcDamages(f).map(x=>x.id));if(!row.damageIds?.length)ready=false;else if(!row.damageIds.every(x=>valid.has(x)))issues.push(`Choose Lasting Damage that ${gtPcName(f)} has.`);}
