function gtPcRefresh(g){const host=document.getElementById('gt-pc-panel');if(host)host.outerHTML=gtPostCyclePanel(g);}
function gtPostCycleChange(event,g){const t=event.target,kind=t.dataset.gtPcKind,fid=t.dataset.gtPcAction;if(!fid)return;const rows=gtPcRows(g);if(kind==='action'){if(!t.value)rows.delete(fid);else rows.set(fid,{action:t.value,injuryIds:[],damageIds:[]});}else{const row=rows.get(fid);if(!row)return;if(kind==='target'){row.targetFighterId=t.value;row.injuryIds=[];}if(kind==='injury'){const set=new Set(row.injuryIds||[]);if(t.checked)set.add(t.value);else set.delete(t.value);row.injuryIds=[...set];}}gtPcRefresh(g);}
function gtPcRemoveEffects(f,ids){const removed=new Set(ids);f.injuries=(f.injuries||[]).filter(x=>!removed.has(x.id));if(Array.isArray(f.effects))f.effects=f.effects.filter(x=>!removed.has(x.id)&&!removed.has(x.injuryId));else if(f.effects)for(const key of ['injuries','lasting damages','rig-glitches'])if(Array.isArray(f.effects[key]))f.effects[key]=f.effects[key].filter(x=>!removed.has(x.id));for(const key of ['lastingDamages','damages','rigGlitches'])if(Array.isArray(f[key]))f[key]=f[key].filter(x=>!removed.has(x.id));for(const e of f.equipment||[])e.effects=(e.effects||[]).filter(x=>!removed.has(x.injuryId));const skills=(f.skillDetails||[]).filter(x=>removed.has(x.injuryId));f.skillDetails=(f.skillDetails||[]).filter(x=>!removed.has(x.injuryId));for(const s of skills)if(!f.skillDetails.some(x=>x.name===s.name)&&!(f.advancements||[]).some(x=>x.name===s.name))f.skills=(f.skills||[]).filter(x=>x!==s.name);}
function gtPcAddInjury(f,rule){const injury={id:id(),presetId:rule.id,name:gtPcName(rule),category:'injuries',at:now(),typeSpecificData:{...(rule.type_specific_data||{})}};f.injuries??=[];f.injuries.push(injury);f.effects=Array.isArray(f.effects)?f.effects:[];const aliases={movement:'M',weapon_skill:'WS',ballistic_skill:'BS',strength:'S',toughness:'T',wounds:'W',initiative:'I',attacks:'A',save:'Sv',leadership:'Ld',cool:'Cl',willpower:'Wil',intelligence:'Int'};for(const m of rule.fighter_effect_modifiers||rule.modifiers||[])f.effects.push({id:id(),injuryId:injury.id,name:injury.name,category:'Injury',stat:aliases[m.stat_name]||m.stat_name||m.stat,amount:Number(m.numeric_value??m.default_numeric_value??m.amount??0),operation:m.operation});}
